using AudioGuide.Data;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using System.Security;
namespace AudioGuide.Business;
public interface IMediaService { Task<object> Translate(int locationId, int languageId); Task<string> Generate(int translationId); Task<string> Upload(int translationId, byte[] data); }
public class MediaService(IRepository repo, IConfiguration config, IHttpClientFactory clients) : IMediaService
{
    public async Task<object> Translate(int locationId, int languageId) { var key = config["AZURE_TRANSLATOR_KEY"]; var region = config["AZURE_TRANSLATOR_REGION"]; if (string.IsNullOrEmpty(key) || string.IsNullOrEmpty(region)) throw new AppError(503, "Chưa cấu hình AZURE_TRANSLATOR_KEY/REGION. Bạn có thể nhập bản dịch thủ công."); var lang = await repo.Db.Languages.FindAsync(languageId) ?? throw new AppError(404, "Không tìm thấy ngôn ngữ"); var src = await repo.Db.Translations.Include(x => x.Language).FirstOrDefaultAsync(x => x.LocationId == locationId && x.Language.Code == "vi") ?? throw new AppError(404, "Cần nội dung gốc tiếng Việt"); using var req = new HttpRequestMessage(HttpMethod.Post, "https://api.cognitive.microsofttranslator.com/translate?api-version=3.0&from=vi&to=" + Uri.EscapeDataString(lang.Code)) { Content = JsonContent.Create(new[] { new { Text = src.Name }, new { Text = src.ShortDescription }, new { Text = src.NarrationText }, new { Text = src.HistoryText } }) }; req.Headers.Add("Ocp-Apim-Subscription-Key", key); req.Headers.Add("Ocp-Apim-Subscription-Region", region); using var res = await clients.CreateClient().SendAsync(req); if (!res.IsSuccessStatusCode) throw new AppError(502, "Dịch vụ dịch chưa sẵn sàng. Kiểm tra khóa, vùng và hạn mức."); var json = JsonDocument.Parse(await res.Content.ReadAsStringAsync()); var result = json.RootElement.EnumerateArray().Select(x => x.GetProperty("translations")[0].GetProperty("text").GetString()).ToArray(); return new { locationId, languageId, name = result[0], shortDescription = result[1], narrationText = result[2], historyText = result[3], status = "Draft", isMachineTranslated = true }; }
    public async Task<string> Generate(int translationId) { var key = config["AZURE_SPEECH_KEY"]; var region = config["AZURE_SPEECH_REGION"]; if (string.IsNullOrEmpty(key) || string.IsNullOrEmpty(region)) throw new AppError(503, "Chưa cấu hình AZURE_SPEECH_KEY/REGION. Có thể tải audio lên hoặc dùng giọng đọc trình duyệt."); if (!System.Text.RegularExpressions.Regex.IsMatch(region, "^[a-z0-9-]+$")) throw new AppError(400, "Vùng Azure không hợp lệ"); var t = await repo.Db.Translations.Include(x => x.Language).FirstOrDefaultAsync(x => x.Id == translationId) ?? throw new AppError(404, "Không tìm thấy nội dung"); using var voiceReq = new HttpRequestMessage(HttpMethod.Get, $"https://{region}.tts.speech.microsoft.com/cognitiveservices/voices/list"); voiceReq.Headers.Add("Ocp-Apim-Subscription-Key", key); using var voiceRes = await clients.CreateClient().SendAsync(voiceReq); if (!voiceRes.IsSuccessStatusCode) throw new AppError(502, "Không lấy được danh sách giọng Azure"); using var voices = JsonDocument.Parse(await voiceRes.Content.ReadAsStringAsync()); var voice = voices.RootElement.EnumerateArray().FirstOrDefault(x => x.GetProperty("Locale").GetString() == t.Language.TtsVoiceCode); if (voice.ValueKind == JsonValueKind.Undefined) throw new AppError(400, "Azure không hỗ trợ giọng đã chọn"); var ssml = $"<speak version='1.0' xml:lang='{SecurityElement.Escape(t.Language.TtsVoiceCode)}'><voice name='{SecurityElement.Escape(voice.GetProperty("ShortName").GetString())}'>{SecurityElement.Escape(t.NarrationText)}</voice></speak>"; using var req = new HttpRequestMessage(HttpMethod.Post, $"https://{region}.tts.speech.microsoft.com/cognitiveservices/v1") { Content = new StringContent(ssml, Encoding.UTF8, "application/ssml+xml") }; req.Headers.Add("Ocp-Apim-Subscription-Key", key); req.Headers.Add("X-Microsoft-OutputFormat", "audio-24khz-48kbitrate-mono-mp3"); using var res = await clients.CreateClient().SendAsync(req); if (!res.IsSuccessStatusCode) throw new AppError(502, "Sinh audio thất bại. Kiểm tra dịch vụ Azure."); return await Store(t.Id, await res.Content.ReadAsByteArrayAsync(), ".mp3", "TTS"); }
    public async Task<string> Upload(int translationId, byte[] data) { if (!await repo.Db.Translations.AnyAsync(x => x.Id == translationId)) throw new AppError(404, "Không tìm thấy nội dung"); if (data.Length < 12 || data.Length > 20 * 1024 * 1024) throw new AppError(400, "Audio cần từ 12 byte đến 20 MB"); string ext; if (Encoding.ASCII.GetString(data, 0, 4) == "OggS") ext = ".ogg"; else if (Encoding.ASCII.GetString(data, 0, 4) == "RIFF" && Encoding.ASCII.GetString(data, 8, 4) == "WAVE") ext = ".wav"; else if (Encoding.ASCII.GetString(data, 0, 3) == "ID3" || (data[0] == 255 && (data[1] & 224) == 224)) ext = ".mp3"; else throw new AppError(400, "Chỉ chấp nhận MP3, OGG, WAV hợp lệ"); return await Store(translationId, data, ext, "Upload"); }
    private async Task<string> Store(int id, byte[] data, string ext, string source) { var root = config["MEDIA_PATH"] ?? "media"; Directory.CreateDirectory(root); var file = Guid.NewGuid().ToString("N") + ext; await File.WriteAllBytesAsync(Path.Combine(root, file), data); var old = await repo.Db.Audios.FirstOrDefaultAsync(x => x.TranslationId == id); if (old == null) repo.Db.Audios.Add(new() { TranslationId = id, FileUrl = "/media/" + file, Source = source }); else { old.FileUrl = "/media/" + file; old.Source = source; old.CreatedAt = DateTime.UtcNow; } await repo.Save(); return "/media/" + file; }
}
